usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Admin.Organization.Groups.Update(
		context.TODO(),
		"group_id",
		openai.AdminOrganizationGroupUpdateParams{
			Name: "string",
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
